namespace PA.Tickets.Domain.Workflow;
public sealed class WorkflowStepInstance
{public string StepCode{get;}public WorkflowStepStatus Status{get;private set;}public string? BranchKey{get;}public DateTimeOffset? StartedAt{get;private set;}public DateTimeOffset? CompletedAt{get;private set;}public string? FailureReason{get;private set;}public WorkflowStepInstance(string stepCode,string? branchKey=null){StepCode=stepCode;BranchKey=branchKey;Status=WorkflowStepStatus.Pending;}internal void Activate(DateTimeOffset now){if(Status==WorkflowStepStatus.Pending){Status=WorkflowStepStatus.Active;StartedAt=now;}}internal void Complete(DateTimeOffset now){if(Status!=WorkflowStepStatus.Active&&Status!=WorkflowStepStatus.Waiting)throw new InvalidOperationException("Only active workflow steps can complete.");Status=WorkflowStepStatus.Completed;CompletedAt=now;}internal void Wait(){if(Status!=WorkflowStepStatus.Active)throw new InvalidOperationException("Only active steps can wait.");Status=WorkflowStepStatus.Waiting;}internal void Fail(string reason){if(Status is WorkflowStepStatus.Completed or WorkflowStepStatus.Cancelled)throw new InvalidOperationException("Completed steps cannot fail.");Status=WorkflowStepStatus.Failed;FailureReason=reason;}}
public sealed class WorkflowInstance
{
 private readonly Dictionary<string,WorkflowStepInstance> _instances=new(StringComparer.OrdinalIgnoreCase);private readonly List<WorkflowExecutionEvent> _events=[];
 public long Id{get;}public long TicketId{get;}public long WorkflowVersionId{get;}public IReadOnlyCollection<WorkflowStepInstance> Steps=>_instances.Values;public IReadOnlyCollection<WorkflowExecutionEvent> Events=>_events;
 public WorkflowInstance(long id,long ticketId,WorkflowVersion version,DateTimeOffset now){Id=id;TicketId=ticketId;WorkflowVersionId=version.Id;foreach(var s in version.Steps)_instances[s.Code]=new WorkflowStepInstance(s.Code);foreach(var s in version.Steps.Where(s=>!version.Transitions.Any(t=>t.ToStep.Equals(s.Code,StringComparison.OrdinalIgnoreCase)))){_instances[s.Code].Activate(now);_events.Add(new("WORKFLOW_STEP_ACTIVATED",s.Code,now));}}
 public IReadOnlyCollection<string> ActiveSteps=>_instances.Values.Where(x=>x.Status is WorkflowStepStatus.Active or WorkflowStepStatus.Waiting).Select(x=>x.StepCode).ToArray();
 public void CompleteStep(string code,WorkflowVersion version,IReadOnlyDictionary<string,string?> context,DateTimeOffset now){if(!_instances.TryGetValue(code,out var instance))throw new KeyNotFoundException(code);instance.Complete(now);_events.Add(new("WORKFLOW_STEP_COMPLETED",code,now));foreach(var transition in version.Transitions.Where(x=>x.FromStep.Equals(code,StringComparison.OrdinalIgnoreCase))){if(transition.Condition is not null&&!transition.Condition.Evaluate(context))continue;TryActivate(transition.ToStep,version,now);}}
 public void WaitStep(string code,DateTimeOffset now){if(!_instances.TryGetValue(code,out var i))throw new KeyNotFoundException(code);i.Wait();_events.Add(new("WORKFLOW_STEP_WAITING",code,now));}
 public void FailStep(string code,string reason,DateTimeOffset now){if(!_instances.TryGetValue(code,out var i))throw new KeyNotFoundException(code);if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Failure reason is required.");i.Fail(reason);_events.Add(new("WORKFLOW_STEP_FAILED",code,now,reason));}
 public void Cancel(string reason,DateTimeOffset now){foreach(var i in _instances.Values.Where(x=>x.Status is WorkflowStepStatus.Active or WorkflowStepStatus.Waiting))i.Fail(reason);_events.Add(new("WORKFLOW_CANCELLED","",now,reason));}
 private void TryActivate(string code,WorkflowVersion version,DateTimeOffset now){var target=version.Steps.Single(x=>x.Code.Equals(code,StringComparison.OrdinalIgnoreCase));var inbound=version.Transitions.Where(x=>x.ToStep.Equals(code,StringComparison.OrdinalIgnoreCase)).Select(x=>_instances[x.FromStep]).ToArray();var completed=inbound.Count(x=>x.Status==WorkflowStepStatus.Completed);var should=target.JoinRule switch{WorkflowJoinRule.AllRequired=>inbound.Length>0&&completed==inbound.Length,WorkflowJoinRule.AnyOne=>completed>0,WorkflowJoinRule.Condition=>completed>0,_=>false};if(should){_instances[code].Activate(now);_events.Add(new("WORKFLOW_STEP_ACTIVATED",code,now));}}
}
